          </li>
          <li>
            {t('providers.ollamaReturnStep')}
          </li>
        </ol>
      </div>

      <button
        onClick={checkStatus}
        className="w-full py-2 text-sm rounded-lg border border-ch-gold/50 text-ch-gold hover:bg-ch-gold/10 transition"
      >
        {t('providers.refresh')}
      </button>

      <button
        onClick={() => setShowAdvanced(!showAdvanced)}
        className="w-full text-xs text-ch-ink-dim hover:text-ch-ink-mute transition"
      >
        {showAdvanced
          ? t('providers.hide')
          : t('providers.advanced')}
        : {t('providers.customOllamaUrl')}
      </button>

      {showAdvanced && (
        <div className="space-y-2">
          <input
            type="text"
            value={customUrl}
            onChange={e => setCustomUrl(e.target.value)}
            placeholder="http://localhost:11434"
            className="w-full bg-ch-bg-raised border border-ch-line-strong text-white rounded-lg px-4 py-3 text-sm focus:outline-none focus:border-amber-500"
          />
          {error && <p className="text-red-400 text-xs">{error}</p>}
          <button
            onClick={connect}
            disabled={connecting || !customUrl.trim()}
            className="w-full py-2.5 bg-brand text-white text-sm font-semibold rounded-lg hover:opacity-90 transition disabled:opacity-50"
          >
            {connecting
              ? t('providers.connecting')
              : t('providers.connect')}
          </button>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { api } from '../core/api/client';

interface Props {
  provider: string;
  currentModel: string;
  onChanged: () => void;
}

export function ModelSelector({ provider, currentModel, onChanged }: Props) {
  const { t } = useTranslation();

  const [models, setModels] = useState<string[]>([]);
  const [selected, setSelected] = useState(currentModel);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    api<{ models: string[] }>(`/api/providers/${provider}/models`)
      .then(data => setModels(data.models))
      .catch(console.error);
  }, [provider]);

  async function save(model: string) {
    setSaving(true);
    try {
      await api('/api/providers/active', {
        method: 'PUT',
        body: JSON.stringify({ provider, model }),
      });
      setSelected(model);
      onChanged();
    } catch (err) {
      console.error('Failed to set model:', err);
    } finally {
      setSaving(false);
    }
  }

  if (!models.length) return null;

  return (
    <div>
      <label style={{
        display: 'block',
        fontFamily: "'JetBrains Mono', ui-monospace, monospace",
        fontSize: 9, letterSpacing: '0.16em', textTransform: 'uppercase',
        color: 'rgba(237,240,244,0.38)', marginBottom: 6,
      }}>
        {t('providers.model')}
      </label>
      <select
        value={selected}
        onChange={e => save(e.target.value)}
        disabled={saving}
        style={{
          width: '100%', boxSizing: 'border-box',
          background: 'rgba(34,40,48,0.55)', border: '1px solid rgba(230,235,242,0.14)',
          color: '#EDF0F4', borderRadius: 4, padding: '8px 12px', fontSize: 13,
          outline: 'none', opacity: saving ? 0.5 : 1,
        }}
      >
        {models.map(m => (
          <option key={m} value={m}>{m}</option>
        ))}
      </select>
    </div>
  );
}

